class Solution {
public:
    int fixedPoint(vector<int>& arr) {
        int low = 0, high = (int)arr.size() - 1;
        int ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == mid) {
                ans = mid;
                high = mid - 1;
            } else if (arr[mid] < mid) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int fixedPoint(int[] arr) {
        int low = 0, high = arr.length - 1;
        int ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == mid) {
                ans = mid;
                high = mid - 1;
            } else if (arr[mid] < mid) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

var fixedPoint = function(arr) {
    let low = 0, high = arr.length - 1;
    let ans = -1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (arr[mid] === mid) {
            ans = mid;
            high = mid - 1;
        } else if (arr[mid] < mid) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
